hooks.command:
f=$(jq -r '.tool_input.file_path // empty')
case "$f" in
  ~*|./*|*/./*|*//*|../*|*/../*|*/..) ;;
  "$HOME"/.agents/states/*/memories/*/*memories/aesthetic-evaluator/*|"$HOME"/.agents/states/*/works/*memories/aesthetic-evaluator/*|"$HOME"/.agents/states/*/archive/*memories/aesthetic-evaluator/*|"$HOME"/.agents/states/*/journals/*memories/aesthetic-evaluator/*|"$HOME"/.agents/states/*/backlogs/*memories/aesthetic-evaluator/*|"$HOME"/.agents/states/*/notion/*memories/aesthetic-evaluator/*) ;;
  "$HOME"/.agents/states/*/memories/aesthetic-evaluator/*)
    exit 0 ;;
  README.md|docs/*|*/docs/*|"$HOME"/.agents/states/*) ;;
  REVIEW-*|*/REVIEW-*|report-*|*/report-*|*.review.md)
    exit 0 ;;
esac
echo '{"hookSpecificOutput":{"hookEventName":"PreToolUse","permissionDecision":"deny","permissionDecisionReason":"Write/Edit is fenced: this critic may only write to its own state-root memory folder or a report file (REVIEW-*, report-*, *.review.md) outside protected project state systems. Return findings in your response instead of editing."}}'
